class Solution {
    private fun factors(input:Int):IntArray{
        var value=input;
        val result=mutableListOf<Int>();
        var factor=2;
        while(factor*factor<=value){
            if(value%factor==0){
                result.add(factor);
                while(value%factor==0)value/=factor
            };
            factor++
        };
        if(value>1)result.add(value);
        return result.toIntArray()
    }
    fun findValidSplit(nums:IntArray):Int{
        val last=HashMap<Int,Int>();
        for(i in nums.indices)for(factor in factors(nums[i]))last[factor]=i;
        var boundary=0;
        for(i in 0 until nums.lastIndex){
            for(factor in factors(nums[i]))boundary=maxOf(boundary,last[factor]!!);
            if(i==boundary)return i
        };
        return -1
    }
}

